# add_dahw_al_ard.py
import database as db

def add_dahw_al_ard():
    """Add Dahw al-Ard prayer to mafatih table with translation below Arabic"""
    
    # متن کامل با ترجمه زیر عربی
    full_text = """اللّٰهُمَّ داحِىَ الكَعْبَةِ، وَ فالِقَ الْحَبَّةِ، وَ صارِفَ اللَّزْبَةِ، وَ كاشِفَ كُلِّ كُرْبَةٍ، أَسْأَلُكَ فِى هٰذَا الْيَوْمِ مِنْ أَيَّامِكَ الَّتِى أَعْظَمْتَ حَقَّها، وَ أَقْدَمْتَ سَبْقَها، وَ جَعَلْتَها عِنْدَ الْمُؤْمِنِينَ وَدِيعَةً، وَ إِلَيْكَ ذَرِيعَةً، وَ بِرَحْمَتِكَ الْوَسِيعَةِ، أَنْ تُصَلِّىَ عَلَىٰ مُحَمَّدٍ عَبْدِكَ الْمُنْتَجَبِ فِى الْمِيثاقِ الْقَرِيبِ يَوْمَ التَّلاقِ فاتِقِ كُلِّ رَتْقٍ، وَ داعٍ إِلىٰ كُلِّ حَقٍّ، وَ عَلَىٰ أَهْلِ بَيْتِهِ الْأَطْهارِ، الْهُداةِ الْمَنارِ، دَعائِمِ الْجَبَّارِ، وَ وُلاةِ الْجَنَّةِ وَ النَّارِ، وَ أَعْطِنا فِى يَوْمِنا هٰذَا مِنْ عَطائِكَ الْمَخْزُونِ غَيْرَ مَقْطُوعٍ وَ لَا مَمْنُوعٍ، تَجْمَعُ لَنا بِهِ التَّوْبَةَ، وَ حُسْنَ الْأَوْبَةِ؛

خدایا؛ ای گسترانندۀ کعبه و شکافندۀ دانه و برگردانندۀ سختی و برطرف‌کنندۀ هر گرفتاری، از تو می‌خواهم در این روز از روزهایت که حقّش را بزرگ گرداندی و سبقتش را پیش انداختی و آن را نزد اهل ایمان امانت و به‌سوی خود وسیله قرار دادی و به رحمت گسترده‌ات که بر محمّد درود فرستی آن بنده برگزیده‌ات در پیمان نزدیک، روز دیدار، شکافندۀ هر امر بسته و دعوت‌کننده به‌حق و بر اهل‌بیت پاکش، آن راهنمایان و روشن‌کنندگان راه حق، ستون‌های قدرت و متولّیان بهشت و دوزخ و عطا کن به ما از عطای در خزانه‌ات که نه بریده شود و نه منع گردد تا به‌وسیلۀ آن رجوع و بازگشت خوبی برای ما فراهم نمایی؛

يَا خَيْرَ مَدْعُوٍّ، وَ أَكْرَمَ مَرْجُوٍّ، يَا كَفِىُّ يَا وَفِىُّ، يَا مَنْ لُطْفُهُ خَفِيٌّ، الْطُفْ لِي بِلُطْفِكَ، وَ أَسْعِدْنِى بِعَفْوِكَ، وَ أَيِّدْنِى بِنَصْرِكَ، وَ لَا تُنْسِنِى كَرِيمَ ذِكْرِكَ، بِوُلاةِ أَمْرِكَ، وَ حَفَظَةِ سِرِّكَ، وَ احْفَظْنِى مِنْ شَوائِبِ الدَّهْرِ إِلىٰ يَوْمِ الْحَشْرِ وَ النَّشْرِ، وَ أَشْهِدْنِى أَوْلِياءَكَ عِنْدَ خُرُوجِ نَفْسِى، وَ حُلُولِ رَمْسِى، وَانْقِطاعِ عَمَلِى، وَانْقِضاءِ أَجَلِى. اللّٰهُمَّ وَاذْكُرْنِى عَلَىٰ طُولِ الْبِلىٰ إِذا حَلَلْتُ بَيْنَ أَطْباقِ الثَّرىٰ، وَ نَسِيَنِى النَّاسُونَ مِنَ الْوَرىٰ، وَ أَحْلِلْنِى دارَ الْمُقامَةِ، وَ بَوِّئْنِى مَنْزِلَ الْكَرامَةِ؛

‌ای بهترین خوانده‌شده و کریم‌ترین امیدشده، ای کفایت‌کننده، ای بخشندۀ کامل، ای آن‌که مهربانی‌اش پنهانی است، به مهربانی‌ات به من مهربانی کن و به گذشتت خوشبختم نما و به یاری‌ات حمایتم کن و از یاد کریمانه‌ات فراموشم مکن به‌حق متولیان امرت و نگهبانان رازت و از گرفتاری‌های روزگار تا روز قیامت و برانگیخته شدن حفظم کن هنگام بیرون آمدن جانم و فرورفتن در قبرم و تمام شدن کارم و سپری شدن عمرم، اولیایت را به بالینم حاضر کن، خدایا یادم کن، بر طول پوسیدگی، زمانی‌که در میان توده‌های خاک فرود آیم و فراموش‌کنندگان از مردم فراموشم کنند و در خانۀ اقامت فرودم آر و در منزل کرامت جایم ده؛

وَاجْعَلْنِى مِنْ مُرافِقِى أَوْلِيائِكَ وَ أَهْلِ اجْتِبائِكَ وَاصْطِفائِكَ، وَ بارِكْ لِى فِى لِقائِكَ، وَارْزُقْنِى حُسْنَ الْعَمَلِ قَبْلَ حُلُولِ الْأَجَلِ بَرِيئاً مِنَ الزَّلَلِ وَ سُوءِ الْخَطَلِ. اللّٰهُمَّ وَ أَوْرِدْنِى حَوْضَ نَبِيِّكَ مُحَمَّدٍ صَلَّى اللّٰهُ عَلَيْهِ وَ آلِهِ وَاسْقِنِى مِنْهُ مَشْرَباً رَوِيّاً سائِغاً هَنِيئاً لَاأَظْمَأُ بَعْدَهُ، وَ لَا أُحَلَّأُ وِرْدَهُ، وَ لَا عَنْهُ أُذادُ، وَاجْعَلْهُ لِى خَيْرَ زادٍ، وَ أَوْفىٰ مِيعادٍ يَوْمَ يَقُومُ الْأَشْهادُ. اللّٰهُمَّ وَالْعَنْ جَبابِرَةَ الْأَوَّلِينَ وَالْآخِرِينَ وَ بِحُقُوقِ أَوْلِيائِكَ الْمُسْتَأْثِرِينَ. اللّٰهُمَّ وَاقْصِمْ دَعائِمَهُمْ، وَ أَهْلِكْ أَشْياعَهُمْ وَ عامِلَهُمْ، وَ عَجِّلْ مَهالِكَهُمْ، وَاسْلُبْهُمْ مَمالِكَهُمْ، وَ ضَيِّقْ عَلَيْهِمْ مَسالِكَهُمْ، وَالْعَنْ مُساهِمَهُمْ وَ مُشارِكَهُمْ؛

و از دوستان اولیایت و برگزیدگان و خاصان درگاهت قرارم ده و ملاقاتت را بر من مبارک گردان و پیش از فر رسیدن پایان عمرم حُسن عمل روزی‌ام فرما، درحالی‌که پاک از لغزش‌ها و گفتار بی‌پایه و منطق باشم. خدایا مرا به حوض پیامبرت محمّد (درود خدا بر او و خاندانش) وارد کن و از آن به من بنوشان، نوشاندنی سیراب‌کننده، روان و گوارا که پس از آن هرگز تشنه نشوم و از ورود به آن طرد نگردم و از آن منع نشوم و آن را قرار ده برایم بهترین توشه و کامل‌ترین وعده‌گاه، روزی که گواهان بپا می‌خیزند. خدایا لعنت کن گردنکشان گذشته و آینده را، هم آنان‌که حقوق اولیایت را به ناحق به خود اختصاص دادند. خدایا پایه‌هایشان را بشکن و پیروان و عُمّالشان را نابود ساز، زمینه‌های هلاکتشان را به زودی فراهم کن و کشورهایشان را از دستشان بگیر و راه‌هایشان را بر آنان تنگ کن و بر آنان‌که با آنان سهیم و شریک‌اند لعنت فرست؛

اللّٰهُمَّ وَ عَجِّلْ فَرَجَ أَوْلِيائِكَ، وَارْدُدْ عَلَيْهِمْ مَظالِمَهُمْ، وَ أَظْهِرْ بِالْحَقِّ قائِمَهُمْ، وَاجْعَلْهُ لِدِينِكَ مُنْتَصِراً، وَ بِأَمْرِكَ فِى أَعْدائِكَ مُؤْتَمِراً. اللّٰهُمَّ احْفُفْهُ بِمَلائِكَةِ النَّصْرِ، وَ بِما أَلْقَيْتَ إِلَيْهِ مِنَ الْأَمْرِ فِى لَيْلَةِ الْقَدْرِ، مُنْتَقِماً لَكَ حَتّىٰ تَرْضىٰ، وَ يَعُودَ دِينُكَ بِهِ وَ عَلَىٰ يَدَيْهِ جَدِيداً غَضّاً، وَ يَمْحَضَ الْحَقَّ مَحْضاً، وَ يَرْفُضَ الْباطِلَ رَفْضاً. اللّٰهُمَّ صَلِّ عَلَيْهِ وَ عَلَىٰ جَمِيعِ آبائِهِ، وَاجْعَلْنا مِنْ صَحْبِهِ وَ أُسْرَتِهِ، وَابْعَثْنا فِى كَرَّتِهِ، حَتّىٰ نَكُونَ فِى زَمانِهِ مِنْ أَعْوانِهِ. اللّٰهُمَّ أَدْرِكْ بِنا قِيامَهُ، وَ أَشْهَدْنا أَيَّامَهُ وَ صَلِّ عَلَيْهِ، وَارْدُدْ إِلَيْنا سَلامَهُ، وَالسَّلامُ عَلَيْهِ وَ رَحْمَةُ اللّٰهِ وَ بَرَكاتُهُ.

خدایا در گشایش کار دوستانت شتاب کن و حقوق تاراج‌رفتۀ آنان را به آنان بازگردان و قائم آنان را بر پایۀ حق آشکار کن و او را یاری‌کنندۀ دینت بدار و درباره دشمنانت اطاعت‌کننده به فرمانت قرار ده. خدایا فرشتگان پیروزی را گرداگرد او بدار و به آن دستوری که در شب قدر به او القا کردی او را انتقام‌گیرنده خویش قرار ده تا جایی که خشنود شوی و دینت به‌وسیلۀ او و به‌دست او به‌گونه‌ای نو تازه بازگردد و حق به‌طور کامل ناب شود و باطل به‌صورت همه‌جانبه به دور افکنده گردد. خدایا بر او و همۀ پدرانش درود فرست و ما را از هم‌نشینان و خاندانش قرار بده و در زمان بازگشتش ما را برانگیز تا در دوران او در شمار یارانش باشیم. خدایا رسیدن به قیامش را روزی ما کن و در روزگارش ما را حاضر کن و بر او درود فرست و سلام او را به ما برگردان، درود و رحمت خدا و برکاتش بر او باد."""

    tafsir_text = """📖 **شرح اعمال روز دحوالارض (۲۵ ذی‌قعده)**

✨ **دحوالارض** به معنای پهن شدن زمین از زیر کعبه بر روی آب است.

🕌 در این روز عظیم‌الشأن، اعمال زیر سفارش شده است:

1️⃣ **غسل** - مستحب است

2️⃣ **ذکر فراوان خدا** 

3️⃣ **روزه** - برابر با روزه هفتاد سال

4️⃣ **نماز دو رکعتی** - در هر رکعت پس از حمد، ۵ مرتبه سوره شمس خوانده شود

5️⃣ **خواندن دعای دحوالارض** (اللّٰهُمَّ داحِیَ الْکَعْبَةِ)

6️⃣ **زیارت امام رضا (ع)** - برترین اعمال این روز

📝 در روایت از امام رضا (ع) آمده است که در شب ۲۵ ذی‌قعده، حضرت ابراهیم و حضرت عیسی متولد شده‌اند و زمین از زیر کعبه پهن شده است. هرکه این روز را روزه بدارد، مانند آن است که شصت ماه روزه داشته است.

✨ همچنین در این روز، حضرت قائم (عج) قیام خواهد کرد."""

    # ثبت در دیتابیس
    item_id = db.add_mafatih_item(
        category="special",
        title="دعای روز دحوالارض (۲۵ ذی‌قعده)",
        arabic_text=full_text,  # متن کامل با ترجمه زیر عربی
        translation_text=None,  # چون ترجمه در خود متن عربی گنجانده شده
        tafsir_text=tafsir_text,
        slug="dahw_al_ard"
    )
    
    print(f"✅ دعای دحوالارض با شناسه {item_id} در دیتابیس ثبت شد.")
    return item_id

if __name__ == "__main__":
    add_dahw_al_ard()